describe('Show / Match', () => {
  it('Show renders children only when the condition holds', () => {
    const on = mount(<Show when={1}>{T('yes')}</Show>);
    expect(on.json()).toContain('yes');
    on.unmount();
    const off = mount(<Show when={0} fallback={T('no')}>{T('yes')}</Show>);
    expect(off.json()).toContain('no');
    off.unmount();
  });
  it('Show with no fallback renders nothing rather than an empty box', () => {
    const m = mount(<Show when={false}>{T('yes')}</Show>);
    expect(m.json()).toBe('null');
    m.unmount();
  });
  it('Match picks the matching case, else the fallback', () => {
    const hit = mount(<Match<'a' | 'b'> value="b" cases={{ a: T('A'), b: T('B') }} />);
    expect(hit.json()).toContain('B');
    hit.unmount();
    const miss = mount(<Match<'a' | 'z'> value="z" cases={{ a: T('A') }} fallback={T('none')} />);
    expect(miss.json()).toContain('none');
    miss.unmount();
  });
});

