describe('Countdown', () => {
  beforeEach(() => jest.useFakeTimers());
  afterEach(() => jest.useRealTimers());
  it('shows the remaining time through its template', () => {
    const m = mount(<Countdown testID="cd" initialSeconds={30} template="Resend in {time}" />);
    expect(m.json()).toContain('Resend in');
    m.unmount();
  });
  it('ticks down and reports completion once', () => {
    const onDone = jest.fn();
    const m = mount(<Countdown testID="cd" initialSeconds={2} doneText="Resend" onDone={onDone} />);
    // one second per act: the next timeout is scheduled by the re-render the
    // previous tick caused, so a single 3000ms jump only ever fires the first
    for (let i = 0; i < 3; i += 1) act(() => { jest.advanceTimersByTime(1000); });
    expect(onDone).toHaveBeenCalledTimes(1);
    expect(m.json()).toContain('Resend');
    m.unmount();
  });
  it('starts done when there is nothing to count', () => {
    const m = mount(<Countdown testID="cd" initialSeconds={0} doneText="Go" />);
    expect(m.json()).toContain('Go');
    m.unmount();
  });
});

