describe('ErrorBoundary', () => {
  const Boom = () => { throw new Error('render exploded'); };
  it('catches a child that throws, reports it, and keeps the app up', () => {
    const onError = jest.fn();
    const err = jest.spyOn(console, 'error').mockImplementation(() => undefined);
    const m = mount(
      <ErrorBoundary onError={onError}>
        <Boom />
      </ErrorBoundary>,
    );
    expect(onError).toHaveBeenCalled();
    expect(m.json()).not.toBe('null');
    err.mockRestore();
    m.unmount();
  });
  it('offers a retry that remounts the subtree', () => {
    let fail = true;
    const Flaky = () => {
      if (fail) throw new Error('render exploded');
      return T('recovered');
    };
    const err = jest.spyOn(console, 'error').mockImplementation(() => undefined);
    const m = mount(<ErrorBoundary><Flaky /></ErrorBoundary>);
    // the fallback offers the only in-process recovery there is: remount and
    // see. A genuinely broken screen throws again and lands back here.
    const retries = m.tree.root
      .findAll((n) => typeof (n.props as Record<string, unknown>).onPress === 'function', { deep: true })
      .map((n) => (n.props as { onPress: () => void }).onPress);
    fail = false;
    for (const retry of retries) act(() => retry());
    expect(m.json()).toBeTruthy();
    err.mockRestore();
    m.unmount();
  });

  it('renders its children untouched when nothing throws', () => {
    const m = mount(<ErrorBoundary><View testID="ok">{T('fine')}</View></ErrorBoundary>);
    expect(m.json()).toContain('fine');
    m.unmount();
  });
});

describe('toast queue', () => {
  afterEach(() => { for (const t of getToasts()) dismissToast(t.id); });
  it('queues a message and hands it to subscribers', () => {
    const seen = jest.fn();
    const off = subscribeToasts(seen);
    showToast('Saved');
    expect(getToasts().map((t) => t.message)).toContain('Saved');
    expect(seen).toHaveBeenCalled();
    off();
  });
  it('refuses a blank message and de-duplicates the same one', () => {
    showToast('   ');
    expect(getToasts()).toHaveLength(0);
    showToast('Twice');
    showToast('Twice');
    expect(getToasts()).toHaveLength(1);
  });
  it('dismisses by id', () => {
    showToast('Bye', 'success');
    const id = getToasts()[0]!.id;
    dismissToast(id);
    expect(getToasts().some((t) => t.id === id)).toBe(false);
  });
  it('dismisses from the close button, not from a press anywhere on the card', () => {
    const m = mount(<Toaster />);
    act(() => showToast('Dismiss me'));
    expect(m.json()).toContain('Dismiss me');
    const close = m.tree.root
      .findAll((n) => (n.props as Record<string, unknown>).testID === 'toast-close', { deep: true })
      .map((n) => (n.props as { onPress?: () => void }).onPress)
      .filter((fn): fn is () => void => typeof fn === 'function');
    expect(close.length).toBeGreaterThan(0);
    act(() => close[0]!());
    expect(getToasts().some((t) => t.message === 'Dismiss me')).toBe(false);
    m.unmount();
  });

  it('Toaster renders nothing when the queue is empty, and the message when it is not', () => {
    const empty = mount(<Toaster />);
    expect(empty.json()).toBe('null');
    empty.unmount();
    const shown = mount(<Toaster />);
    act(() => showToast('Rendered'));
    expect(shown.json()).toContain('Rendered');
    shown.unmount();
  });
});
